import{d as u,C as t,o as m,c,j as a,a as s,E as r,a3 as g}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第五十七章","description":"以正奇、禁令与四个民自反省治理，区分王弼崇本息末的解法与常见读法。","frontmatter":{"title":"道德经第五十七章","description":"以正奇、禁令与四个民自反省治理，区分王弼崇本息末的解法与常见读法。","category":"guide","aliases":["道德经第五十七章","老子第五十七章","dao de jing chapter 57"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-57.md","filePath":"daoism/dao-de-jing/chapter-57.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-57.md"},q=u({...p,setup(b){const o=[{id:"regular-irregular-and-noninterference",label:"以正治国，以奇用兵",showLabel:!0,sentences:[["以",{text:"正",glossary:"zheng"},"治国，以",{text:"奇",glossary:"qi"},"用兵，以",{text:"无事",glossary:"wushi"},{text:"取",glossary:"qu"},"天下。"]],note:["【白话】就句面说：以正则治理国家，以奇变使用军队，以不妄造事端治理天下。三者如何相连，需要连后文辨明，不能只作并排口号。","【王弼注择要】「以道治国，崇本以息末；以正治国，立辟以攻末。」王弼又说「以正治国，则奇正起也」，将正治与奇兵相生的局面，与无事取天下作比较。","【读法】辟在这段注中取法辟、法度。循此注，正不直接等同道；立法攻末而本未立，反会走到奇兵。正奇的常见平行读法可作另一读法，不冒称王弼之意。"]},{id:"prohibitions-and-poverty",label:"天下多忌讳，而民弥贫",showLabel:!0,sentences:[["吾何以知其然哉？以此：天下多",{text:"忌讳",glossary:"jihui"},"，而民",{text:"弥",glossary:"mi"},"贫；"]],note:["【白话】我凭什么知道如此呢？就凭这些现象：天下禁忌和禁令越多，百姓反而越贫困。下面几组句子接着列出同类反效。","【王弼注择要】回说诸句时，注以「多皆舍本以治末，故以致此也」说明治理何以走向相反结果。","【读法】忌讳在此联系治理中的禁限，弥为更加。这是章内对繁禁的反省，不能把任何必要约束都视作贫困的原因。"]},{id:"self-serving-instruments",label:"民多利器，国家滋昏",showLabel:!0,sentences:[["民多",{text:"利器",glossary:"liqi"},"，国家",{text:"滋",glossary:"zi"},{text:"昏",glossary:"hun"},"；"]],note:["【白话】人们各自谋利的器用、手段越多，国家反而越趋昏乱。此处白话依王弼对利器的解释。","【王弼注择要】「利器，凡所以利己之器也。」古注将它落实到利己所用，不只限于武器。","【读法】利器另列本章义项，与第三十六章国家治理凭借的解释分开；滋为更加，昏指秩序昏乱。现代器具是否有益，应看用途和影响，不能由此一概否定技术。"]},{id:"artifice-and-strange-products",label:"人多伎巧，奇物滋起",showLabel:!0,sentences:[["人多",{text:"伎巧",glossary:"jiqiao"},"，",{text:"奇物",glossary:"qiwu"},{text:"滋",glossary:"zi"},"起；"]],note:["【白话】人们逞弄的伎巧越多，奇异、邪巧的事物就越纷起。句子把巧伪的手段与由此滋生的事态连起来。","【王弼注择要】「巧伪生，则邪事起。」注从巧伪说明奇物，不只以稀罕新颖为判断。","【读法】伎巧在本段指机巧伪饰，奇物取奇异邪巧之物；这是特定批评语境，不用来抹去学习、创造与有益工艺的价值。"]},{id:"prominent-laws-and-theft",label:"法令滋彰，盗贼多有",showLabel:!0,sentences:[["法令",{text:"滋",glossary:"zi"},{text:"彰",glossary:"zhang"},"，盗贼多有。"]],note:["【白话】法令越发彰明、繁显，盗贼却越发增多。经文继续指出，名目上的整齐不一定消除实际失序。","【王弼注择要】「立正欲以息邪，而奇兵用。」注将这一反效连回开头正、奇相生的问题，再以舍本治末概括。","【读法】滋与彰分别为愈加、显明。经句不是经过现代研究确认的单一因果定律，也不能据它直接取消一切法制；应追问规则是否只增名目，却未处理造乱之因。"]},{id:"four-self-arising-responses",label:"我无为，而民自化",showLabel:!0,sentences:[["故圣人云：我",{text:"无为",glossary:"wuwei"},"，而民",{text:"自化",glossary:"zihua"},"；我",{text:"好",glossary:"hao"},"静，而民",{text:"自正",glossary:"zizheng"},"；我",{text:"无事",glossary:"wushi"},"，而民自富；我无欲，而民自",{text:"朴",glossary:"pu"},"。"]],note:["【白话】所以圣人说：我不妄为，百姓得以自行化育；我喜好清静，百姓得以自行端正；我不妄兴事端，百姓得以自行富足；我不以私欲驱动，百姓得以自行归于质朴。","【王弼注择要】「上之所欲，民从之速也。」注又以「此四者崇本以息末也」收束，重在在上者自身的欲求与施为。","【读法】好读 hào；自正指自行归正，不与开头立辟攻末的正简单等同。四个民自写治理方向，仍须让人有安生与行动的条件，不保证什么都不管就必然富足。"]}],i=[{id:"zheng",term:"正",sense:2},{id:"qi",term:"奇",sense:1},{id:"wushi",term:"无事",sense:1},{id:"qu",term:"取",sense:1},{id:"jihui",term:"忌讳",sense:1},{id:"mi",term:"弥",sense:1},{id:"liqi",term:"利器",sense:2},{id:"zi",term:"滋",sense:1},{id:"hun",term:"昏",sense:1},{id:"jiqiao",term:"伎巧",sense:1},{id:"qiwu",term:"奇物",sense:1},{id:"zhang",term:"彰",sense:1},{id:"wuwei",term:"无为",sense:1},{id:"zihua",term:"自化",sense:1},{id:"hao",term:"好",sense:1},{id:"zizheng",term:"自正",sense:1},{id:"pu",term:"朴",sense:2}];return(x,e)=>{const n=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),c("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第五十七章",tabindex:"-1"},[s("道德经第五十七章 "),a("a",{class:"header-anchor",href:"#道德经第五十七章","aria-label":'Permalink to "道德经第五十七章"'},"​")],-1)),r(n,{title:"为什么治理越用力，反而可能生出更多事端",summary:"本章把正、奇、无事并列提出，再以禁讳、利器、伎巧、法令写出治理的反效，最后转向无为、好静、无事、无欲。王弼尤其把以正治国读成以法辟攻末，不能直接把三句当成他赞同的三条并行原则。",points:[{label:"先读",text:"先辨正治、奇兵与无事三句，再看后文用哪些现象检验治理。"},{label:"再辨",text:"王注的利器是利己之器，伎巧偏于巧伪；不要一概等同技术、知识或兵器。"},{label:"后看",text:"四个我与四个民自对应，关注在上者如何减少欲求与滋扰。"}],hint:"奇读 qí；忌讳读 jì huì，伎巧读 jì qiǎo，好静的好读 hào。正在本章依王注联系法辟，不与自正混为一义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:o,glossary:i}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"以正治国，以奇用兵，以无事取天下。",tone:"先分清注法",guide:"王弼把正治与奇兵的相生，连到舍本治末的反效，不作三条平行赞语。"},{text:"法令滋彰，盗贼多有。",tone:"检验治理的结果",guide:"规则名目之外，继续看贫困、巧伪与盗乱是否实际减少。"},{text:"我无欲，而民自朴。",tone:"回到在上者之欲",guide:"四个民自都对应一个我，先反省治理者自己制造了什么趋逐。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:i}),e[4]||(e[4]=g("",15))])}}});export{y as __pageData,q as default};
